svg.script:

(function() {
  var phrases = [
    "Hamza Taif",
    "Software Engineering",
    "Full-Stack App Developer",
    "AI Engineering",
    "Building useful software."
  ];
  var target = document.getElementById("type-target");
  if (!target) return;

  var pIndex = 0;
  var cIndex = 0;
  var isDeleting = false;
  var typeSpeed = 90;

  function typeLoop() {
    var current = phrases[pIndex];
    if (isDeleting) {
      target.textContent = current.substring(0, cIndex - 1);
      cIndex--;
      typeSpeed = 45;
    } else {
      target.textContent = current.substring(0, cIndex + 1);
      cIndex++;
      typeSpeed = 90;
    }

    if (!isDeleting && cIndex === current.length) {
      typeSpeed = 1800; // Pause at end of line
      isDeleting = true;
    } else if (isDeleting && cIndex === 0) {
      isDeleting = false;
      pIndex = (pIndex + 1) % phrases.length;
      typeSpeed = 400; // Pause before next line
    }

    setTimeout(typeLoop, typeSpeed);
  }

  typeLoop();
})();
